//! APR<->tick conversion: round-trip, monotonicity, error paths, builder ergonomics, and
//! byte-exact contract parity against `TickLib.priceToTick` / `TickLib.tickToPrice`.
//!
//! The parity constants are generated by `fixtures/GenApr.t.sol` run against the midnight contracts
//! (rev f47568c9) with `forge test --match-contract GenApr -vv` at tick spacing 4. To regenerate:
//!   cp fixtures/GenApr.t.sol "<midnight>/test/GenApr.t.sol" && \
//!     (cd "<midnight>" && forge test --match-contract GenApr -vv) && rm "<midnight>/test/GenApr.t.sol"

use nocturne::*;

const SPACING: u64 = DEFAULT_TICK_SPACING as u64;

fn u256(x: u128) -> U256 {
    U256::from(x)
}

// ---- Contract parity: TickLib.priceToTick(price, 4) → (tick, tickToPrice(tick)) ----
// (price_wad, expected_tick, expected_tick_price)
const PRICE_TO_TICK: &[(u128, u64, u128)] = &[
    (100_000_000_000_000_000, 2932, 100_244_400_000_000_000),
    (200_000_000_000_000_000, 3096, 201_561_800_000_000_000),
    (500_000_000_000_000_000, 3372, 500_000_000_000_000_000),
    (700_000_000_000_000_000, 3544, 702_207_100_000_000_000),
    (900_000_000_000_000_000, 3816, 901_540_200_000_000_000),
    (950_000_000_000_000_000, 3964, 950_385_600_000_000_000),
    (990_000_000_000_000_000, 4296, 990_129_700_000_000_000),
    (999_000_000_000_000_000, 4760, 999_015_800_000_000_000),
    (1_000_000_000_000_000_000, 6744, 1_000_000_000_000_000_000),
    (333_333_333_333_333_333, 3236, 336_639_600_000_000_000),
];

// ---- Contract parity: full apr → price → tick → price chain ----
// (apr_pct, ttm_secs, expected_tick, expected_tick_price)
const APR_CHAIN: &[(f64, u64, u64, u128)] = &[
    (5.0, 31_536_000, 3976, 953_129_400_000_000_000),
    (10.0, 31_536_000, 3836, 910_039_200_000_000_000),
    (7.2, 15_768_000, 4040, 965_499_200_000_000_000),
    (2.5, 7_884_000, 4392, 993_862_500_000_000_000),
    (15.0, 2_592_000, 4256, 987_977_200_000_000_000),
    (3.0, 63_072_000, 3940, 944_429_200_000_000_000),
];

#[test]
fn price_to_tick_matches_contract_exactly() {
    for &(price, tick, tick_price) in PRICE_TO_TICK {
        assert_eq!(
            price_to_tick(u256(price), SPACING).unwrap(),
            tick,
            "price_to_tick({price})"
        );
        // The returned tick's price matches the contract's tickToPrice(tick).
        assert_eq!(
            tick_to_price(tick).unwrap(),
            u256(tick_price),
            "tick_to_price({tick})"
        );
    }
}

#[test]
fn exact_rate_outputs_match_sdk_vectors() {
    let cases = [
        (
            4,
            9_999_999_000_000_000_000_000_000u128,
            121_666_654_500_000_000_000_000_000u128,
        ),
        (
            1_000,
            136_985_301_369_863_013_698_631,
            1_666_654_500_000_000_000_000_011,
        ),
        (
            2_000,
            937_174_312_787_315_883_292,
            11_402_287_472_245_676_580_053,
        ),
        (3_372, 1_000_000_000_000_000_000, 12_166_666_666_666_666_667),
        (5_000, 297_588_532_588_446, 3_620_660_479_826_093),
        (6_740, 100_000_010_001, 1_216_666_788_346),
        (6_744, 0, 0),
    ];
    for (tick, rate, apr_30d) in cases {
        assert_eq!(tick_to_rate(tick).unwrap(), U256::from(rate), "tick {tick}");
        assert_eq!(
            tick_to_apr_wad(tick, 2_592_000).unwrap(),
            U256::from(apr_30d),
            "tick {tick}"
        );
        assert_eq!(
            tick_to_apr_wad(tick, SECONDS_PER_YEAR).unwrap(),
            U256::from(rate),
            "one-year tick {tick}"
        );
    }

    assert_eq!(tick_to_rate(0), Err(SimError::ZeroPrice));
    assert_eq!(tick_to_apr_wad(3_372, 0), Err(SimError::ZeroTimeToMaturity));
}

#[test]
fn apr_chain_matches_contract_exactly() {
    for &(apr, ttm, tick, tick_price) in APR_CHAIN {
        let t = apr_to_tick(apr, ttm, SPACING).unwrap();
        assert_eq!(t, tick, "apr_to_tick({apr}, {ttm})");
        assert_eq!(
            tick_to_price(t).unwrap(),
            u256(tick_price),
            "tick price for apr {apr}"
        );
        // The tick is accessible (aligned to spacing).
        assert_eq!(t % SPACING, 0, "tick {t} aligned to spacing");
    }
}

#[test]
fn round_trip_within_one_spacing_step() {
    // Start from an accessible tick, annualize, invert, and land within one spacing step.
    let ttms = [31_536_000u64, 15_768_000, 7_884_000, 2_592_000, 63_072_000];
    for ttm in ttms {
        for tick in (3000u64..=5000).step_by(SPACING as usize) {
            let apr = tick_to_apr(tick, ttm).unwrap();
            let back = apr_to_tick(apr, ttm, SPACING).unwrap();
            let diff = (back as i64 - tick as i64).abs();
            assert!(
                diff <= SPACING as i64,
                "round-trip tick={tick} ttm={ttm} apr={apr} -> {back} (diff {diff})"
            );
        }
    }
}

#[test]
fn round_trip_from_apr_within_one_spacing_step() {
    // Start from an APR, snap to a tick, re-annualize, re-snap: the two ticks differ by <= spacing.
    let ttm = 31_536_000u64;
    for apr_hundredths in (50u64..=2000).step_by(37) {
        let apr = apr_hundredths as f64 / 100.0;
        let t1 = apr_to_tick(apr, ttm, SPACING).unwrap();
        let apr_back = tick_to_apr(t1, ttm).unwrap();
        let t2 = apr_to_tick(apr_back, ttm, SPACING).unwrap();
        let diff = (t2 as i64 - t1 as i64).abs();
        assert!(diff <= SPACING as i64, "apr={apr} t1={t1} t2={t2}");
        // Realized APR never exceeds the target (snap raises price, lowers rate).
        assert!(
            apr_back <= apr + 1e-9,
            "realized apr {apr_back} exceeds target {apr}"
        );
    }
}

#[test]
fn higher_apr_gives_lower_tick_and_price() {
    let ttm = 31_536_000u64;
    let t5 = apr_to_tick(5.0, ttm, SPACING).unwrap();
    let t10 = apr_to_tick(10.0, ttm, SPACING).unwrap();
    let t15 = apr_to_tick(15.0, ttm, SPACING).unwrap();
    // Higher APR -> lower price -> lower tick.
    assert!(
        t15 < t10 && t10 < t5,
        "expected 15%<10%<5% ticks, got {t15} {t10} {t5}"
    );
    assert!(tick_to_price(t15).unwrap() < tick_to_price(t5).unwrap());
}

#[test]
fn tick_to_apr_is_decreasing_in_tick() {
    let ttm = 31_536_000u64;
    let mut prev = f64::INFINITY;
    for tick in (100u64..=6000).step_by(200) {
        let apr = tick_to_apr(tick, ttm).unwrap();
        assert!(
            apr < prev,
            "apr should decrease with tick: tick={tick} apr={apr} prev={prev}"
        );
        prev = apr;
    }
}

#[test]
fn error_paths() {
    // price > 1e18 (WAD) has no tick.
    assert_eq!(
        price_to_tick(u256(1_000_000_000_000_000_001), SPACING),
        Err(SimError::PriceGreaterThanOne)
    );
    assert_eq!(
        price_to_tick(u256(500_000_000_000_000_000), 0),
        Err(SimError::InvalidTickSpacing(0))
    );
    assert_eq!(
        price_to_tick(u256(500_000_000_000_000_000), 5),
        Err(SimError::InvalidTickSpacing(5))
    );
    // Zero time-to-maturity cannot be annualized.
    assert_eq!(tick_to_apr(3976, 0), Err(SimError::ZeroTimeToMaturity));
    // Out-of-range tick propagates from tick_to_price.
    assert!(matches!(
        tick_to_apr(MAX_TICK + 1, 31_536_000),
        Err(SimError::TickOutOfRange(_))
    ));
}

// ---- Builder ergonomics ----

const MIDNIGHT: Address = [0x11; 20];
const LOAN: Address = [0x22; 20];
const RATIFIER: Address = [0xbb; 20];
const MATURITY: u64 = 1_800_000_000;
// now such that ttm = 1 year.
const NOW: u64 = MATURITY - 31_536_000;

fn a_market() -> Market {
    MarketBuilder::new(1, MIDNIGHT, LOAN)
        .collateral(
            [0x33; 20],
            u256(860_000_000_000_000_000),
            U256::from(1u64),
            [0x44; 20],
        )
        .maturity(MATURITY)
        .rcf_threshold(U256::from(1000u64))
        .build()
}

#[test]
fn builder_lend_apr_assets_produces_valid_offer() {
    let cbps = [0u16; 7]; // zero settlement fee for a clean sizing check
    let target_assets = 1_000_000u128;

    let offer = OfferBuilder::new(a_market(), [0x55; 20])
        .lend()
        .apr(5.0, NOW)
        .expiry(MATURITY)
        .assets(target_assets, NOW, cbps)
        .ratifier(RATIFIER)
        .build_checked()
        .expect("build_checked should succeed");

    assert!(offer.buy, "lend() is a buy offer");

    // Tick matches apr_to_tick for the same (apr, ttm, spacing).
    let expected_tick = apr_to_tick(5.0, 31_536_000, SPACING).unwrap();
    assert_eq!(word_to_u128(&offer.tick), Some(expected_tick as u128));
    assert_eq!(expected_tick, 3976, "matches contract-parity tick");

    // max_units matches buyer_assets_to_units on the built offer.
    let expected_units = buyer_assets_to_units(&offer, u256(target_assets), NOW, cbps).unwrap();
    assert_eq!(offer.max_units, u128::try_from(expected_units).unwrap());
    assert!(offer.max_units > 0);
    assert_eq!(offer.max_assets, 0);
}

#[test]
fn builder_borrow_side_sizes_seller() {
    let cbps = [0u16; 7];
    let offer = OfferBuilder::new(a_market(), [0x55; 20])
        .borrow()
        .apr(8.0, NOW)
        .expiry(MATURITY)
        .assets(2_000_000, NOW, cbps)
        .ratifier(RATIFIER)
        .build_checked()
        .expect("build_checked should succeed");

    assert!(!offer.buy, "borrow() is a sell offer");
    let expected = seller_assets_to_units(&offer, u256(2_000_000), NOW, cbps).unwrap();
    assert_eq!(offer.max_units, u128::try_from(expected).unwrap());
}

#[test]
fn builder_does_not_panic_on_extreme_apr() {
    // A huge APR clamps to a valid accessible tick (apr_to_tick never overflows the price range).
    let cbps = [0u16; 7];
    let res = OfferBuilder::new(a_market(), [0x55; 20])
        .lend()
        .apr(1000.0, NOW)
        .expiry(MATURITY)
        .assets(1_000_000, NOW, cbps)
        .ratifier(RATIFIER)
        .build_checked();
    assert!(
        res.is_ok(),
        "high APR still yields a valid accessible tick: {res:?}"
    );
}

#[test]
fn builder_surfaces_conversion_error_at_build_checked() {
    // A target so large that units overflow u128 is captured and surfaced (no panic).
    // Buy offer at tick 3372 (price 0.5e18): units = ceil(MAX * 1e18 / 0.5e18) ≈ 2 * MAX > u128.
    let cbps = [0u16; 7];
    let res = OfferBuilder::new(a_market(), [0x55; 20])
        .lend()
        .tick(3372)
        .expiry(MATURITY)
        .assets(u128::MAX, NOW, cbps)
        .ratifier(RATIFIER)
        .build_checked();
    assert_eq!(res.unwrap_err(), BuildError::UnitsOverflow);
}

#[test]
fn builder_build_still_works_without_apr_assets() {
    // The infallible path is unchanged for tick/units usage.
    let offer = OfferBuilder::new(a_market(), [0x55; 20])
        .lend()
        .tick(8)
        .ratifier(RATIFIER)
        .max_units(1_000_000)
        .build();
    assert_eq!(word_to_u128(&offer.tick), Some(8));
}
